-- Schema version 1 of the FitLog database, captured from the
-- generated drift code before the v2 migration was written.
-- Used by test/db/migration_test.dart to build a real v1 file.

CREATE TABLE "app_settings" ("id" TEXT NOT NULL, "unit_weight" TEXT NOT NULL DEFAULT 'kg', "unit_length" TEXT NOT NULL DEFAULT 'cm', "unit_distance" TEXT NOT NULL DEFAULT 'km', "default_rest_seconds" INTEGER NOT NULL DEFAULT 90, "rest_sound_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("rest_sound_enabled" IN (0, 1)), "set_check_sound_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("set_check_sound_enabled" IN (0, 1)), "pr_alert_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("pr_alert_enabled" IN (0, 1)), "theme_mode" TEXT NOT NULL DEFAULT 'dark', "locale" TEXT NOT NULL DEFAULT 'nl', "onboarding_done" INTEGER NOT NULL DEFAULT 0 CHECK ("onboarding_done" IN (0, 1)), "exercises_seeded" INTEGER NOT NULL DEFAULT 0 CHECK ("exercises_seeded" IN (0, 1)), "bar_weight_kg" REAL NOT NULL DEFAULT 20.0, "available_plates_kg" TEXT NOT NULL DEFAULT '[25,20,15,10,5,2.5,1.25]', "auto_lock_seconds" INTEGER NOT NULL DEFAULT 60, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "body_measurements" ("id" TEXT NOT NULL, "measured_at" INTEGER NOT NULL, "type" TEXT NOT NULL, "value" REAL NOT NULL, "note" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "exercises" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "primary_muscle" TEXT NOT NULL, "secondary_muscles" TEXT NOT NULL DEFAULT '[]', "equipment" TEXT NULL, "category" TEXT NOT NULL, "instructions" TEXT NULL, "image_asset" TEXT NULL, "is_custom" INTEGER NOT NULL DEFAULT 0 CHECK ("is_custom" IN (0, 1)), "is_archived" INTEGER NOT NULL DEFAULT 0 CHECK ("is_archived" IN (0, 1)), "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "personal_records" ("id" TEXT NOT NULL, "exercise_id" TEXT NOT NULL REFERENCES exercises (id) ON DELETE CASCADE, "record_type" TEXT NOT NULL, "value" REAL NOT NULL, "workout_set_id" TEXT NULL, "achieved_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "progress_photos" ("id" TEXT NOT NULL, "taken_at" INTEGER NOT NULL, "file_name" TEXT NOT NULL, "pose" TEXT NOT NULL, "note" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "routine_exercises" ("id" TEXT NOT NULL, "routine_id" TEXT NOT NULL REFERENCES routines (id) ON DELETE CASCADE, "exercise_id" TEXT NOT NULL REFERENCES exercises (id), "sort_order" INTEGER NOT NULL, "rest_seconds" INTEGER NULL, "superset_group" INTEGER NULL, "notes" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "routine_folders" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "sort_order" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "routine_sets" ("id" TEXT NOT NULL, "routine_exercise_id" TEXT NOT NULL REFERENCES routine_exercises (id) ON DELETE CASCADE, "sort_order" INTEGER NOT NULL, "set_type" TEXT NOT NULL DEFAULT 'normal', "target_reps" INTEGER NULL, "target_weight_kg" REAL NULL, "target_duration_seconds" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "routines" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "notes" TEXT NULL, "folder_id" TEXT NULL REFERENCES routine_folders (id) ON DELETE SET NULL, "sort_order" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "last_performed_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "user_profile" ("id" TEXT NOT NULL, "display_name" TEXT NULL, "birth_date" INTEGER NULL, "sex" TEXT NULL, "height_cm" REAL NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "workout_exercises" ("id" TEXT NOT NULL, "workout_id" TEXT NOT NULL REFERENCES workouts (id) ON DELETE CASCADE, "exercise_id" TEXT NOT NULL REFERENCES exercises (id), "sort_order" INTEGER NOT NULL, "rest_seconds" INTEGER NOT NULL DEFAULT 90, "superset_group" INTEGER NULL, "notes" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "workout_sets" ("id" TEXT NOT NULL, "workout_exercise_id" TEXT NOT NULL REFERENCES workout_exercises (id) ON DELETE CASCADE, "sort_order" INTEGER NOT NULL, "set_type" TEXT NOT NULL DEFAULT 'normal', "weight_kg" REAL NULL, "reps" INTEGER NULL, "duration_seconds" INTEGER NULL, "distance_m" REAL NULL, "rpe" REAL NULL, "is_completed" INTEGER NOT NULL DEFAULT 0 CHECK ("is_completed" IN (0, 1)), "completed_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "workouts" ("id" TEXT NOT NULL, "routine_id" TEXT NULL REFERENCES routines (id) ON DELETE SET NULL, "name" TEXT NOT NULL, "started_at" INTEGER NOT NULL, "ended_at" INTEGER NULL, "notes" TEXT NULL, "total_volume_kg" REAL NOT NULL DEFAULT 0.0, "total_sets" INTEGER NOT NULL DEFAULT 0, "duration_seconds" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
CREATE INDEX idx_body_measurements_type_date ON body_measurements (type, measured_at);
CREATE INDEX idx_personal_records_exercise_type ON personal_records (exercise_id, record_type);
CREATE INDEX idx_progress_photos_taken_at ON progress_photos (taken_at);
CREATE INDEX idx_routine_exercises_routine ON routine_exercises (routine_id);
CREATE INDEX idx_routine_sets_routine_exercise ON routine_sets (routine_exercise_id);
CREATE INDEX idx_workout_exercises_exercise ON workout_exercises (exercise_id);
CREATE INDEX idx_workout_exercises_workout ON workout_exercises (workout_id);
CREATE INDEX idx_workout_sets_workout_exercise ON workout_sets (workout_exercise_id);
CREATE INDEX idx_workouts_started_at ON workouts (started_at);
